from contextlib import asynccontextmanager

import aiosqlite


async def init_db(db_path: str) -> None:
    async with aiosqlite.connect(db_path) as db:
        await db.executescript("""
            PRAGMA journal_mode=WAL;

            CREATE TABLE IF NOT EXISTS click_events (
                id          INTEGER PRIMARY KEY AUTOINCREMENT,
                session_id  TEXT    NOT NULL,
                item_id     TEXT    NOT NULL,
                query       TEXT    NOT NULL DEFAULT '',
                position    INTEGER NOT NULL DEFAULT 0,
                ts          INTEGER NOT NULL
            );

            CREATE TABLE IF NOT EXISTS item_similarities (
                item_id     TEXT    NOT NULL,
                similar_id  TEXT    NOT NULL,
                score       REAL    NOT NULL,
                updated_at  INTEGER NOT NULL,
                PRIMARY KEY (item_id, similar_id)
            );

            CREATE TABLE IF NOT EXISTS items (
                item_id     TEXT    PRIMARY KEY,
                name        TEXT    NOT NULL,
                category    TEXT    NOT NULL DEFAULT '',
                price       REAL    NOT NULL DEFAULT 0.0,
                image_url   TEXT    NOT NULL DEFAULT '',
                in_stock    INTEGER NOT NULL DEFAULT 1
            );

            CREATE INDEX IF NOT EXISTS idx_clicks_session ON click_events (session_id);
            CREATE INDEX IF NOT EXISTS idx_clicks_item    ON click_events (item_id);
            CREATE INDEX IF NOT EXISTS idx_clicks_ts      ON click_events (ts);
            CREATE INDEX IF NOT EXISTS idx_sim_item       ON item_similarities (item_id);
        """)
        await db.commit()


@asynccontextmanager
async def searchrec_lifespan(db_path: str):
    await init_db(db_path)
    yield
